const input = $json.body ?? $json;
const uuid = (v) => typeof v === 'string' && /^[0-9a-f]{8}-[0-9a-f-]{27,}$/i.test(v);
if (input.workflowKey !== "account.email.verify.send" || input.contract !== "ancfz-v2-stage-action-v1") throw new Error('Unsupported workflow contract.');
for (const k of ['actionId','tenantId','sessionId','eventId','correlationId']) if (!uuid(input[k])) throw new Error('Missing server-issued '+k);
if (!Number.isInteger(input.attempt) || input.attempt < 1) throw new Error('Missing attempt.');
return [{json: {actionId:input.actionId,tenantId:input.tenantId,sessionId:input.sessionId,eventId:input.eventId,correlationId:input.correlationId,attempt:input.attempt,workflowKey:input.workflowKey,contract:input.contract}}];

const rows = $json.items;
if (!Array.isArray(rows) || rows.length !== 1) throw new Error('Expected one authorized Node action; no bulk execution.');
const action = rows[0];
const env = $('Validate Dispatch Envelope').first().json;
if (action.workflowKey !== "account.email.verify.send" || action.stageKey !== "account_creation" || action.contract !== env.contract) throw new Error('Stage/action contract mismatch.');
for (const k of ['actionId','tenantId','sessionId','eventId','correlationId']) if (action[k] !== env[k]) throw new Error('Claim correlation mismatch: '+k);
if (action.attempt !== env.attempt || !Number.isInteger(action.actionRevision) || action.actionRevision < 1) throw new Error('Stale action revision or attempt.');
for (const k of ['opportunityId','catalogVersionId','idempotencyKey','actionKey','approvedPayload']) if (!action[k]) throw new Error('Missing approved Node field: '+k);
if (action.actionKey !== "account.email.verify.send") throw new Error('Action identity mismatch.');
if (action.providerEnabled !== true || action.v2Authorized !== true || action.purposeConsentVerified !== true || action.actionConfirmationVerified !== true) throw new Error('Node did not explicitly authorize this V2 side effect.');
if (typeof action.approvedPayload !== 'object' || Array.isArray(action.approvedPayload)) throw new Error('Approved payload missing.');
return [{json:action}];

const source = $('Require V2 Stage Authorization').first().json;
const result = $json;
if (result.accepted !== true || result.evidenceTier !== 'provider_record_verified' || result.stageKey !== "account_creation") throw new Error('Node has not independently verified provider state.');
for (const key of ['actionId','tenantId','sessionId','opportunityId','catalogVersionId','idempotencyKey','actionKey','actionRevision','eventId','correlationId','attempt']) if (result[key] !== source[key]) throw new Error('Node attestation scope mismatch: '+key);
if (typeof result.providerRecordRef !== 'string' || !/^[A-Za-z0-9][A-Za-z0-9._:-]{0,199}$/.test(result.providerRecordRef)) throw new Error('Invalid provider attestation record reference.');
return [{json:{...result,executionReference:$execution.id}}];
